import java.util.List;
public final class Transfer {
    public static void copyFirst(List<Number> source, List<Number> destination) {
        destination.add(source.get(0));
    }
}

import java.util.ArrayList;
import java.util.List;
public final class Caller {
    public static void main(String[] args) {
        List<Double> source = List.of(2.5);
        List<Number> destination = new ArrayList<>();
        Transfer.copyFirst(source, destination);
        Object original = source.get(0);
        Object copied = destination.get(0);
        if (destination.size() != 1 || original != copied) throw new AssertionError();
    }
}

